import { Page, TestInfo } from 'playwright/test';

/**
 * Extends Playwright {@code test} so MERV wraps:
 * - {@code page} — logs (and optional screenshots) after major actions / expects
 * - {@code request} (and {@code page.request}) — attaches Request/Response details onto each API step
 * - when {@code merv.video=true} — highlights actioned elements, stitches a testcase video
 *   (step PNGs only when {@code merv.screenshot=true})
 *
 * @example
 * ```ts
 * import { extendTestWithMervScreenshots } from 'merv-client-playwright';
 * import { test as base } from '@playwright/test';
 *
 * export const test = extendTestWithMervScreenshots(base);
 * export { expect } from '@playwright/test';
 * ```
 */
declare function extendTestWithMervScreenshots<T extends {
    extend: any;
}>(baseTest: T): T;

/**
 * Returns a {@link Page} proxy that logs (and optionally screenshots) **after** major page/locator
 * actions using {@link TestInfo.attach} + {@link MervLogger}.
 * Uses the underlying (unproxied) {@link Page} for {@code screenshot()} to avoid recursion.
 *
 * @param attachToReport when true ({@code merv.screenshot=true}), PNG attachments appear on report steps.
 * @param video when true, highlight the actioned element and queue frames for the testcase video
 *   (even if {@code attachToReport} is false — video-only mode).
 */
declare function wrapPageForMervScreenshots(page: Page, testInfo: TestInfo, attachToReport?: boolean, video?: boolean): Page;

/**
 * Tag {@code test.step} titles so the MERV reporter can classify them as custom step types
 * (see {@link formatMervStepTitle} and {@code merv.report.extra_step_types} in {@code merv.properties}).
 */
/** Uppercase token: letters, digits, underscore only. */
declare function normalizeMervStepTypeToken(stepType: string): string;
/**
 * Prefix a {@code test.step} title so the reporter maps it to a custom step type in JSON/HTML.
 *
 * @example
 * await test.step(formatMervStepTitle('VALIDATION_STEP', 'Password length rule'), async () => { … });
 */
declare function formatMervStepTitle(stepType: string, title: string): string;
interface ParsedMervTaggedTitle {
    tagged: boolean;
    /** Normalized custom type when {@link tagged}; empty when not tagged. */
    stepType: string;
    /** Title without the {@code [MERV:TYPE]} prefix when tagged; otherwise the full title. */
    displayTitle: string;
}
/**
 * Detects {@code [MERV:TYPE] …} at the start of a Playwright step title (after {@code titlePath} join).
 */
declare function parseMervTaggedStepTitle(fullTitle: string): ParsedMervTaggedTitle;
/** Maps Playwright reporter step category to MERV step type string. */
declare function playwrightCategoryToStepType(category: string | undefined): string;
/**
 * Final step type and display title for the report row.
 * MERV-tagged titles override category (usually {@code TEST_STEP} → your custom type).
 */
declare function resolveMervReportStep(fullTitle: string, category: string | undefined): {
    stepType: string;
    displayTitle: string;
};

/**
 * Same role as Java listener handlers for framework plugins: hold test context and expose
 * MERV step helpers. Construct once per test with that test’s {@link TestInfo}.
 *
 * @example
 * ```ts
 * test('flow', async ({ page }, testInfo) => {
 *   const merv = new MervPlaywrightHandler(testInfo);
 *   await merv.data('User', JSON.stringify({ id: 1 }));
 *   await merv.validation('Title', 'Home', await page.title(), true);
 *   merv.info('Environment: staging');
 * });
 * ```
 */
declare class MervPlaywrightHandler {
    private readonly testInfo;
    constructor(testInfo: TestInfo);
    /** TEST_DATA row. Set last arg {@code screenshot: true} for a viewport PNG on this step. */
    data(stepName: string, testdata: string, screenshot?: boolean): Promise<void>;
    /** @deprecated Use {@link data}. */
    addDataStep(stepName: string, testdata: string, screenshot?: boolean): Promise<void>;
    /** ASSERTION row. Optional last arg {@code screenshot: true} captures viewport PNG. */
    validation(stepName: string, expected?: string | null, actual?: string | null, screenshot?: boolean): Promise<void>;
    /** @deprecated Use {@link validation}. Legacy {@code testdata}/{@code prereq} args are ignored. */
    addValidationStep(stepName: string, expected?: string | null, actual?: string | null, testdataOrScreenshot?: string | null | boolean, prereqOrScreenshot?: string | null | boolean, screenshot?: boolean): Promise<void>;
    addCustomStep(stepName: string, status?: string, errorMessage?: string | null): Promise<void>;
    info(infoToAdd: string): Promise<void>;
}

export { MervPlaywrightHandler as M, type ParsedMervTaggedTitle as P, playwrightCategoryToStepType as a, extendTestWithMervScreenshots as e, formatMervStepTitle as f, normalizeMervStepTypeToken as n, parseMervTaggedStepTitle as p, resolveMervReportStep as r, wrapPageForMervScreenshots as w };
